import java.util.*;
final class Definitions {
    static final Set<String> BUILTINS = Set.of("__LINE__", "__FILE__", "__COUNTER__");
    static final String VARIADIC = "__VA_ARGS__",
                        VARIADIC_ERROR =
                            "\"__VA_ARGS__\" can only appear in the expansion of a variadic macro";
    record Position(String file, int line) {
        public String toString() { return file + ":" + line; }
    }
    static final class DefinitionError extends RuntimeException {
        DefinitionError(String message) { super(message); }
    }
    static final class Macro {
        String name;
        List<String> parameters;
        boolean variadic, mainFile;
        List<Lexer.Token> replacement;
        Position position;
        int expanded, tested;
        Macro(String name, List<String> parameters, boolean variadic, List<Lexer.Token> replacement,
              Position position, boolean mainFile) {
            this.name = name;
            this.parameters = parameters == null ? null : List.copyOf(parameters);
            this.variadic = variadic;
            this.replacement = List.copyOf(replacement);
            this.position = position;
            this.mainFile = mainFile;
        }
        String signature() {
            if (parameters == null)
                return name;
            List<String> names = new ArrayList<>(parameters);
            if (variadic)
                names.set(names.size() - 1, "...");
            return name + "(" + String.join(", ", names) + ")";
        }
        boolean identical(Macro other) {
            if (!Objects.equals(parameters, other.parameters) || variadic != other.variadic ||
                replacement.size() != other.replacement.size())
                return false;
            for (int i = 0; i < replacement.size(); i++) {
                Lexer.Token a = replacement.get(i), b = other.replacement.get(i);
                if (!a.spelling().equals(b.spelling()) || a.space() != b.space())
                    return false;
            }
            return true;
        }
    }
    static String checkName(List<Lexer.Token> tokens, String directive) {
        if (tokens.isEmpty())
            return "no macro name given in #" + directive + " directive";
        if (!tokens.getFirst().kind().equals("identifier"))
            return "macro names must be identifiers";
        String name = tokens.getFirst().spelling();
        if (name.equals("defined"))
            return "\"defined\" cannot be used as a macro name";
        if (BUILTINS.contains(name))
            return "cannot " + (directive.equals("define") ? "redefine" : "undefine") +
                " builtin macro \"" + name + "\"";
        return null;
    }
    static Macro parse(List<Lexer.Token> tokens, Position position, boolean mainFile) {
        String error = checkName(tokens, "define");
        if (error != null)
            throw new DefinitionError(error);
        String name = tokens.getFirst().spelling();
        if (name.equals(VARIADIC))
            throw new DefinitionError(VARIADIC_ERROR);
        List<String> parameters = null;
        boolean variadic = false;
        int index = 1;
        if (tokens.size() > 1 && tokens.get(1).spelling().equals("(") && !tokens.get(1).space()) {
            parameters = new ArrayList<>();
            index = 2;
            if (index == tokens.size())
                throw new DefinitionError("missing ')' in macro parameter list");
            if (tokens.get(index).spelling().equals(")"))
                index++;
            else
                while (true) {
                    if (index == tokens.size())
                        throw new DefinitionError("missing ')' in macro parameter list");
                    Lexer.Token token = tokens.get(index);
                    if (token.spelling().equals("...")) {
                        parameters.add(VARIADIC);
                        variadic = true;
                    } else if (token.kind().equals("identifier")) {
                        if (token.spelling().equals(VARIADIC))
                            throw new DefinitionError(VARIADIC_ERROR);
                        if (parameters.contains(token.spelling()))
                            throw new DefinitionError("duplicate macro parameter \"" +
                                                      token.spelling() + "\"");
                        parameters.add(token.spelling());
                    } else
                        throw new DefinitionError("expected parameter name, found \"" +
                                                  token.spelling() + "\"");
                    index++;
                    if (index == tokens.size())
                        throw new DefinitionError("missing ')' in macro parameter list");
                    String following = tokens.get(index++).spelling();
                    if (following.equals(")"))
                        break;
                    if (variadic)
                        throw new DefinitionError("expected ')' after \"...\", found \"" +
                                                  following + "\"");
                    if (!following.equals(","))
                        throw new DefinitionError("expected ',' or ')', found \"" + following +
                                                  "\"");
                }
        }
        List<Lexer.Token> replacement = new ArrayList<>(tokens.subList(index, tokens.size()));
        if (!replacement.isEmpty()) {
            replacement.set(0, replacement.getFirst().spaced(false));
            if (replacement.getFirst().spelling().equals("##") ||
                replacement.getLast().spelling().equals("##"))
                throw new DefinitionError("'##' cannot appear at either end of a macro expansion");
        }
        for (int i = 0; i < replacement.size(); i++) {
            Lexer.Token token = replacement.get(i);
            if (token.kind().equals("identifier") && token.spelling().equals(VARIADIC) && !variadic)
                throw new DefinitionError(VARIADIC_ERROR);
            if (token.spelling().equals("#") && parameters != null &&
                (i + 1 == replacement.size() ||
                 !replacement.get(i + 1).kind().equals("identifier") ||
                 !parameters.contains(replacement.get(i + 1).spelling())))
                throw new DefinitionError("'#' is not followed by a macro parameter");
        }
        return new Macro(name, parameters, variadic, replacement, position, mainFile);
    }
}

import java.util.*;
final class Expander {
    @FunctionalInterface
    interface Diagnostic {
        void record(Definitions.Position position, String kind, String message);
    }
    Map<String, Definitions.Macro> macros;
    Diagnostic diagnostic;
    int counter;
    Map<String, Integer> builtinCounts = new HashMap<>();
    Expander(Map<String, Definitions.Macro> macros, Diagnostic diagnostic) {
        this.macros = macros;
        this.diagnostic = diagnostic;
    }
    void error(Main.Inclusion context, Lexer.Token token, String message) {
        diagnostic.record(context.position(token.line()), "error", message);
    }
    Lexer.Token builtin(Lexer.Token token, Main.Inclusion context) {
        builtinCounts.merge(token.spelling(), 1, Integer::sum);
        String kind = "number", spelling;
        if (token.spelling().equals("__FILE__")) {
            kind = "string";
            spelling = "\"" + context.displayFile + "\"";
        } else if (token.spelling().equals("__LINE__"))
            spelling = Integer.toString(context.position(token.line()).line());
        else
            spelling = Integer.toString(counter++);
        return new Lexer.Token(kind, spelling, token.line(), token.space());
    }
    record Collected(Map<String, List<Lexer.Token>> raw, int consumed, Lexer.Token closing) {}
    Collected collect(Deque<Lexer.Token> pending, Definitions.Macro macro, Lexer.Token token,
                      Main.Inclusion context) {
        List<List<Lexer.Token>> arguments = new ArrayList<>();
        arguments.add(new ArrayList<>());
        List<Lexer.Token> separators = new ArrayList<>();
        int nesting = 0, index = 0, consumed = 0;
        Lexer.Token closing = null;
        for (Lexer.Token current : pending) {
            if (index++ == 0)
                continue;
            if (current.spelling().equals(")") && nesting == 0) {
                closing = current;
                consumed = index;
                break;
            }
            if (current.spelling().equals(",") && nesting == 0) {
                separators.add(current);
                arguments.add(new ArrayList<>());
            } else {
                if (current.spelling().equals("("))
                    nesting++;
                else if (current.spelling().equals(")"))
                    nesting--;
                arguments.getLast().add(current);
            }
        }
        if (closing == null) {
            error(context, token,
                  "unterminated argument list invoking macro \"" + macro.name + "\"");
            return null;
        }
        int count = arguments.size(), fixed = macro.parameters.size() - (macro.variadic ? 1 : 0);
        String message = null;
        if (!macro.variadic && fixed == 0 && (count != 1 || !arguments.getFirst().isEmpty()))
            message =
                "macro \"" + macro.name + "\" passed " + count + " arguments, but takes just 0";
        else if (count < fixed)
            message = "macro \"" + macro.name + "\" requires " + fixed + " arguments, but only " +
                      count + " given";
        else if (count > fixed && !macro.variadic)
            message = "macro \"" + macro.name + "\" passed " + count +
                      " arguments, but takes just " + fixed;
        if (message != null) {
            error(context, token, message);
            return null;
        }
        Map<String, List<Lexer.Token>> raw = new HashMap<>();
        for (int i = 0; i < fixed; i++)
            raw.put(macro.parameters.get(i), arguments.get(i));
        if (macro.variadic) {
            List<Lexer.Token> variable = new ArrayList<>();
            for (int i = fixed; i < count; i++) {
                if (i > fixed)
                    variable.add(separators.get(i - 1));
                variable.addAll(arguments.get(i));
            }
            raw.put(Definitions.VARIADIC, variable);
        }
        return new Collected(raw, consumed, closing);
    }
    Lexer.Token stringize(List<Lexer.Token> tokens, Lexer.Token sharp) {
        StringBuilder text = new StringBuilder("\"");
        for (int i = 0; i < tokens.size(); i++) {
            Lexer.Token token = tokens.get(i);
            if (i > 0 && token.space())
                text.append(' ');
            String spelling = token.spelling();
            if (token.kind().equals("string") || token.kind().equals("character"))
                spelling = spelling.replace("\\", "\\\\").replace("\"", "\\\"");
            text.append(spelling);
        }
        text.append('"');
        return new Lexer.Token("string", text.toString(), sharp.line(), sharp.space());
    }
    List<Lexer.Token> paste(Lexer.Token left, Lexer.Token right, Lexer.Token token,
                            Main.Inclusion context) {
        if (left.kind().equals("placemarker"))
            return List.of(right.spaced(left.space()));
        if (right.kind().equals("placemarker"))
            return List.of(left);
        String spelling = left.spelling() + right.spelling(), kind = Lexer.singleToken(spelling);
        if (kind != null) {
            Set<String> hide = new HashSet<>(left.hide());
            hide.retainAll(right.hide());
            return List.of(new Lexer.Token(kind, spelling, left.line(), left.space(), hide));
        }
        error(context, token,
              "pasting \"" + left.spelling() + "\" and \"" + right.spelling() +
                  "\" does not give a valid preprocessing token");
        return List.of(left, right.spaced(false));
    }
    sealed interface Item permits Tokens, Paste {}
    record Tokens(List<Lexer.Token> tokens) implements Item {}
    record Paste(Lexer.Token token) implements Item {}
    List<Lexer.Token> substitute(Definitions.Macro macro, Map<String, List<Lexer.Token>> raw,
                                 Lexer.Token token, Set<String> hide, Main.Inclusion context) {
        List<Lexer.Token> replacement = macro.replacement;
        List<Item> items = new ArrayList<>();
        Map<String, List<Lexer.Token>> expanded = new HashMap<>();
        int index = 0;
        while (index < replacement.size()) {
            Lexer.Token current = replacement.get(index);
            if (current.spelling().equals("#") && macro.parameters != null) {
                items.add(new Tokens(
                    List.of(stringize(raw.get(replacement.get(index + 1).spelling()), current))));
                index += 2;
                continue;
            }
            if (current.spelling().equals("##"))
                items.add(new Paste(current));
            else if (current.kind().equals("identifier") && raw.containsKey(current.spelling())) {
                boolean adjacent =
                    index > 0 && replacement.get(index - 1).spelling().equals("##") ||
                    index + 1 < replacement.size() &&
                        replacement.get(index + 1).spelling().equals("##");
                List<Lexer.Token> sequence;
                if (adjacent)
                    sequence = raw.get(current.spelling());
                else {
                    if (!expanded.containsKey(current.spelling()))
                        expanded.put(current.spelling(),
                                     expand(raw.get(current.spelling()), context));
                    sequence = expanded.get(current.spelling());
                }
                if (sequence.isEmpty())
                    items.add(new Tokens(List.of(
                        new Lexer.Token("placemarker", "", current.line(), current.space()))));
                else {
                    List<Lexer.Token> copy = new ArrayList<>(sequence);
                    copy.set(0, copy.getFirst().spaced(current.space()));
                    items.add(new Tokens(copy));
                }
            } else
                items.add(new Tokens(List.of(current)));
            index++;
        }
        List<Lexer.Token> pasted = new ArrayList<>();
        index = 0;
        while (index < items.size()) {
            Item item = items.get(index);
            if (item instanceof Paste) {
                Lexer.Token left = pasted.removeLast();
                Item following = items.get(index + 1);
                List<Lexer.Token> right = following instanceof Paste paste
                                              ? List.of(paste.token())
                                              : ((Tokens)following).tokens();
                pasted.addAll(paste(left, right.getFirst(), token, context));
                pasted.addAll(right.subList(1, right.size()));
                index += 2;
            } else {
                pasted.addAll(((Tokens)item).tokens());
                index++;
            }
        }
        List<Lexer.Token> result = new ArrayList<>();
        boolean carry = false;
        for (Lexer.Token current : pasted)
            if (current.kind().equals("placemarker"))
                carry |= current.space();
            else {
                Set<String> combined = new HashSet<>(current.hide());
                combined.addAll(hide);
                result.add(current.substituted(token.line(), current.space() || carry, combined));
                carry = false;
            }
        if (!result.isEmpty())
            result.set(0, result.getFirst().spaced(token.space()));
        return result;
    }
    List<Lexer.Token> expand(List<Lexer.Token> sequence, Main.Inclusion context) {
        Deque<Lexer.Token> pending = new ArrayDeque<>(sequence);
        List<Lexer.Token> result = new ArrayList<>();
        while (!pending.isEmpty()) {
            Lexer.Token token = pending.removeFirst();
            if (!token.kind().equals("identifier") || token.hide().contains(token.spelling())) {
                result.add(token);
                continue;
            }
            if (Definitions.BUILTINS.contains(token.spelling())) {
                result.add(builtin(token, context));
                continue;
            }
            Definitions.Macro macro = macros.get(token.spelling());
            if (macro == null ||
                macro.parameters != null &&
                    (pending.isEmpty() || !pending.peekFirst().spelling().equals("("))) {
                result.add(token);
                continue;
            }
            Map<String, List<Lexer.Token>> raw = Map.of();
            Set<String> hide = new HashSet<>(token.hide());
            if (macro.parameters != null) {
                Collected collected = collect(pending, macro, token, context);
                if (collected == null) {
                    result.add(token);
                    continue;
                }
                raw = collected.raw();
                for (int i = 0; i < collected.consumed(); i++)
                    pending.removeFirst();
                hide.retainAll(collected.closing().hide());
            }
            hide.add(macro.name);
            List<Lexer.Token> replacement = substitute(macro, raw, token, hide, context);
            macro.expanded++;
            if (replacement.isEmpty() && token.space() && !pending.isEmpty())
                pending.addFirst(pending.removeFirst().spaced(true));
            for (int i = replacement.size() - 1; i >= 0; i--)
                pending.addFirst(replacement.get(i));
        }
        return result;
    }
}

import java.util.*;
import java.util.function.Consumer;
final class Expression {
    static final List<Set<String>> LEVELS = List.of(
        Set.of("||"), Set.of("&&"), Set.of("|"), Set.of("^"), Set.of("&"), Set.of("==", "!="),
        Set.of("<", ">", "<=", ">="), Set.of("<<", ">>"), Set.of("+", "-"), Set.of("*", "/", "%"));
    static final class ExpressionError extends RuntimeException {
        ExpressionError(String message) { super(message); }
    }
    sealed interface Node permits Constant, Identifier, Unary, Binary, Conditional {}
    record Constant(long value) implements Node {}
    record Identifier(String name) implements Node {}
    record Unary(String operator, Node operand) implements Node {}
    record Binary(String operator, Node first, Node second) implements Node {}
    record Conditional(Node condition, Node yes, Node no) implements Node {}
    static long integerValue(String spelling) {
        String value = spelling;
        for (String suffix : List.of("ll", "LL", "l", "L"))
            if (value.endsWith(suffix) && value.length() > suffix.length()) {
                value = value.substring(0, value.length() - suffix.length());
                break;
            }
        if (value.matches("0[xX][0-9a-fA-F]+"))
            return Long.parseLong(value.substring(2), 16);
        if (value.matches("0[0-7]*"))
            return Long.parseLong(value, 8);
        if (value.matches("[1-9][0-9]*"))
            return Long.parseLong(value);
        throw new ExpressionError("invalid integer constant \"" + spelling + "\"");
    }
    static long characterValue(String spelling) {
        String value = spelling.substring(1, spelling.length() - 1);
        if (value.length() == 1 && value.charAt(0) != '\'' && value.charAt(0) != '\\')
            return value.charAt(0);
        if (value.length() == 2 && value.charAt(0) == '\\') {
            int result = switch (value.charAt(1)) {
                case 'n' -> 10;
                case 't' -> 9;
                case '\\' -> 92;
                case '\'' -> 39;
                case '"' -> 34;
                case '0' -> 0;
                default -> -1;
            };
            if (result >= 0)
                return result;
        }
        throw new ExpressionError("invalid character constant " + spelling);
    }
    List<Lexer.Token> tokens;
    int position;
    Expression(List<Lexer.Token> tokens) { this.tokens = tokens; }
    String peek() { return position < tokens.size() ? tokens.get(position).spelling() : null; }
    Node expression() {
        Node left = binary(0);
        if ("?".equals(peek())) {
            position++;
            Node yes = expression();
            if (!":".equals(peek()))
                throw new ExpressionError("'?' without following ':'");
            position++;
            left = new Conditional(left, yes, expression());
        }
        return left;
    }
    Node binary(int level) {
        if (level == LEVELS.size())
            return unary();
        Node left = binary(level + 1);
        while (peek() != null && LEVELS.get(level).contains(peek())) {
            String operator = peek();
            position++;
            left = new Binary(operator, left, binary(level + 1));
        }
        return left;
    }
    Node unary() {
        String next = peek();
        if (next != null && Set.of("+", "-", "!", "~").contains(next)) {
            position++;
            return new Unary(next, unary());
        }
        if (position == tokens.size())
            throw new ExpressionError("expected value at end of expression");
        Lexer.Token token = tokens.get(position++);
        if (token.kind().equals("number"))
            return new Constant(integerValue(token.spelling()));
        if (token.kind().equals("character"))
            return new Constant(characterValue(token.spelling()));
        if (token.kind().equals("identifier"))
            return new Identifier(token.spelling());
        if (token.spelling().equals("(")) {
            Node node = expression();
            if (!")".equals(peek()))
                throw new ExpressionError("missing ')' in expression");
            position++;
            return node;
        }
        throw new ExpressionError("expected value before \"" + token.spelling() + "\"");
    }
    static Node parse(List<Lexer.Token> tokens, String directive) {
        if (tokens.isEmpty())
            throw new ExpressionError("#" + directive + " with no expression");
        Expression parser = new Expression(tokens);
        Node tree = parser.expression();
        if (parser.peek() != null)
            throw new ExpressionError("missing binary operator before \"" + parser.peek() + "\"");
        return tree;
    }
    static long binaryValue(String operator, long a, long b) {
        if ((operator.equals("/") || operator.equals("%")) && b == 0)
            throw new ExpressionError("division by zero in #if");
        return switch (operator) {
            case "/" -> a / b;
            case "%" -> a % b;
            case "+" -> a + b;
            case "-" -> a - b;
            case "*" -> a *b;
            case "<<" -> a << b;
            case ">>" -> a >> b;
            case "&" -> a & b;
            case "|" -> a | b;
            case "^" -> a ^ b;
            case "==" -> a == b ? 1 : 0;
            case "!=" -> a != b ? 1 : 0;
            case "<" -> a < b ? 1 : 0;
            case ">" -> a > b ? 1 : 0;
            case "<=" -> a <= b ? 1 : 0;
            default -> a >= b ? 1 : 0;
        };
    }
    record Work(String operation, Node node, String operator) {}
    static long evaluate(Node tree, Consumer<String> warning) {
        Deque<Work> pending = new ArrayDeque<>();
        Deque<Long> values = new ArrayDeque<>();
        pending.push(new Work("evaluate", tree, null));
        while (!pending.isEmpty()) {
            Work work = pending.pop();
            switch (work.operation()) {
            case "evaluate" -> {
                switch (work.node()) {
                case Constant constant -> values.push(constant.value());
                case Identifier identifier -> {
                    warning.accept("identifier \"" + identifier.name() + "\" evaluates to 0");
                    values.push(0L);
                }
                case Unary unary -> {
                    pending.push(new Work("unary", null, unary.operator()));
                    pending.push(new Work("evaluate", unary.operand(), null));
                }
                case Conditional conditional -> {
                    pending.push(new Work("choose", conditional, null));
                    pending.push(new Work("evaluate", conditional.condition(), null));
                }
                case Binary binary -> {
                    if (Set.of("&&", "||").contains(binary.operator())) {
                        pending.push(new Work("logical", binary.second(), binary.operator()));
                        pending.push(new Work("evaluate", binary.first(), null));
                    } else {
                        pending.push(new Work("binary", null, binary.operator()));
                        pending.push(new Work("evaluate", binary.second(), null));
                        pending.push(new Work("evaluate", binary.first(), null));
                    }
                }
                }
            }
            case "choose" -> {
                Conditional conditional = (Conditional)work.node();
                pending.push(new Work(
                    "evaluate", values.pop() != 0 ? conditional.yes() : conditional.no(), null));
            }
            case "logical" -> {
                long first = values.pop();
                if (work.operator().equals("&&") && first == 0 ||
                    work.operator().equals("||") && first != 0)
                    values.push(first != 0 ? 1L : 0L);
                else {
                    pending.push(new Work("truth", null, null));
                    pending.push(new Work("evaluate", work.node(), null));
                }
            }
            case "truth" -> values.push(values.pop() != 0 ? 1L : 0L);
            case "unary" -> {
                long value = values.pop();
                values.push(switch (work.operator()) {
                    case "+" -> value;
                    case "-" -> -value;
                    case "!" -> value == 0 ? 1L : 0L;
                    default -> -value - 1;
                });
            }
            case "binary" -> {
                long second = values.pop(), first = values.pop();
                values.push(binaryValue(work.operator(), first, second));
            }
            }
        }
        return values.pop();
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
final class IncludeManager {
    static final Set<String> STARTS = Set.of("if", "ifdef", "ifndef"),
                             BRANCHES = Set.of("elif", "elifdef", "elifndef", "else");
    static String directiveName(List<Lexer.Token> tokens) {
        return tokens.size() >= 2 && tokens.get(0).spelling().equals("#") &&
                tokens.get(1).kind().equals("identifier")
            ? tokens.get(1).spelling()
            : null;
    }
    static String guard(List<Lexer.LogicalLine> lines) {
        List<List<Lexer.Token>> nonempty = new ArrayList<>();
        for (Lexer.LogicalLine line : lines)
            if (!line.tokens().isEmpty())
                nonempty.add(line.tokens());
        if (nonempty.isEmpty())
            return null;
        List<Lexer.Token> first = nonempty.getFirst(), last = nonempty.getLast();
        if (first.size() != 3 || !"ifndef".equals(directiveName(first)) ||
            !first.get(2).kind().equals("identifier"))
            return null;
        if (last.size() != 2 || !"endif".equals(directiveName(last)))
            return null;
        int depth = 0;
        for (int i = 0; i < nonempty.size(); i++) {
            String name = directiveName(nonempty.get(i));
            if (name != null && BRANCHES.contains(name) && depth == 1)
                return null;
            if (name != null && STARTS.contains(name))
                depth++;
            else if ("endif".equals(name))
                depth--;
            if (depth == 0 && i != nonempty.size() - 1)
                return null;
        }
        return depth == 0 ? first.get(2).spelling() : null;
    }
    static final class SourceFile {
        String path, guard;
        int physicalLines, entered, skipped, outputLines, skippedLines;
        boolean once;
        List<Lexer.LogicalLine> lines;
        SourceFile(String path, String content) {
            this.path = path;
            for (int i = 0; i < content.length(); i++)
                if (content.charAt(i) == '\n')
                    physicalLines++;
            lines = Lexer.source(content);
            guard = IncludeManager.guard(lines);
        }
    }
    Map<String, SourceFile> files = new LinkedHashMap<>();
    String search(String name, boolean quoted) {
        List<String> paths = quoted ? List.of(name, "include/" + name) : List.of("include/" + name);
        for (String path : paths)
            if (Files.isRegularFile(Path.of("input", path)))
                return path;
        return null;
    }
    SourceFile load(String path) throws Exception {
        SourceFile source = files.get(path);
        if (source == null) {
            source = new SourceFile(
                path, Files.readString(Path.of("input", path), StandardCharsets.US_ASCII));
            files.put(path, source);
        }
        return source;
    }
}

import java.util.*;
final class Lexer {
    record Token(String kind, String spelling, int line, boolean space, Set<String> hide) {
        Token(String kind, String spelling, int line, boolean space) {
            this(kind, spelling, line, space, Set.of());
        }
        Token { hide = Set.copyOf(hide); }
        Token spaced(boolean value) { return new Token(kind, spelling, line, value, hide); }
        Token substituted(int line, boolean space, Set<String> hide) {
            return new Token(kind, spelling, line, space, hide);
        }
    }
    record LogicalLine(List<Token> tokens, int start, int end) {}
    record Read(String kind, String spelling, int end) {}
    record Spliced(String text, int[] positions) {}
    static final List<String> PUNCTUATORS = List.of(
        "...", "<<=", ">>=", "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||",
        "*=", "/=", "%=", "+=", "-=", "&=", "^=", "|=", "##", "[", "]", "(", ")", "{", "}", ".",
        "&", "*", "+", "-", "~", "!", "/", "%", "<", ">", "^", "|", "?", ":", ";", "=", ",", "#");
    static boolean identifierStart(char c) {
        return c == '_' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z';
    }
    static boolean digit(char c) { return c >= '0' && c <= '9'; }
    static Read readToken(String text, int position, boolean header) {
        char c = text.charAt(position);
        int length = text.length();
        if (header && c == '<') {
            int closing = text.indexOf('>', position + 1), newline =
                                                               text.indexOf('\n', position + 1);
            if (closing >= 0 && (newline < 0 || closing < newline))
                return new Read("header", text.substring(position, closing + 1), closing + 1);
        }
        if (identifierStart(c)) {
            int end = position + 1;
            while (end < length && (identifierStart(text.charAt(end)) || digit(text.charAt(end))))
                end++;
            return new Read("identifier", text.substring(position, end), end);
        }
        if (digit(c) || c == '.' && position + 1 < length && digit(text.charAt(position + 1))) {
            int end = position + 1;
            while (end < length) {
                char next = text.charAt(end);
                if ("eEpP".indexOf(next) >= 0 && end + 1 < length &&
                    "+-".indexOf(text.charAt(end + 1)) >= 0)
                    end += 2;
                else if (identifierStart(next) || digit(next) || next == '.')
                    end++;
                else
                    break;
            }
            return new Read("number", text.substring(position, end), end);
        }
        if (c == '\'' || c == '"') {
            int end = position + 1;
            while (end < length && text.charAt(end) != '\n') {
                if (text.charAt(end) == c)
                    return new Read(c == '"' ? "string" : "character",
                                    text.substring(position, end + 1), end + 1);
                if (text.charAt(end) == '\\' && end + 1 < length && text.charAt(end + 1) != '\n')
                    end += 2;
                else
                    end++;
            }
        }
        for (String punctuator : PUNCTUATORS)
            if (text.startsWith(punctuator, position))
                return new Read("punctuator", punctuator, position + punctuator.length());
        return new Read("other", String.valueOf(c), position + 1);
    }
    static Spliced splice(String source) {
        StringBuilder text = new StringBuilder();
        List<Integer> positions = new ArrayList<>();
        int index = 0, line = 1;
        while (index < source.length()) {
            if (source.startsWith("\\\n", index)) {
                index += 2;
                line++;
                continue;
            }
            char c = source.charAt(index++);
            text.append(c);
            positions.add(line);
            if (c == '\n')
                line++;
        }
        int[] numbers = new int[positions.size()];
        for (int i = 0; i < numbers.length; i++)
            numbers[i] = positions.get(i);
        return new Spliced(text.toString(), numbers);
    }
    static List<LogicalLine> scan(String text, int[] positions, int start) {
        List<LogicalLine> lines = new ArrayList<>();
        List<Token> tokens = new ArrayList<>();
        int index = 0;
        boolean spaced = true;
        while (index < text.length()) {
            char c = text.charAt(index);
            if (c == ' ') {
                spaced = true;
                index++;
            } else if (c == '\n') {
                int end = positions[index];
                lines.add(new LogicalLine(List.copyOf(tokens), start, end));
                tokens = new ArrayList<>();
                start = end + 1;
                spaced = true;
                index++;
            } else if (text.startsWith("/*", index)) {
                int closing = text.indexOf("*/", index + 2);
                index = closing < 0 ? text.length() : closing + 2;
                spaced = true;
            } else if (text.startsWith("//", index)) {
                int closing = text.indexOf('\n', index + 2);
                index = closing < 0 ? text.length() : closing;
                spaced = true;
            } else {
                boolean header = tokens.size() == 2 && tokens.get(0).spelling().equals("#") &&
                                 tokens.get(1).spelling().equals("include");
                Read read = readToken(text, index, header);
                tokens.add(new Token(read.kind(), read.spelling(), positions[index], spaced));
                index = read.end();
                spaced = false;
            }
        }
        if (!tokens.isEmpty())
            lines.add(new LogicalLine(List.copyOf(tokens), start, positions[positions.length - 1]));
        return lines;
    }
    static List<LogicalLine> source(String text) {
        Spliced spliced = splice(text);
        return scan(spliced.text(), spliced.positions(), 1);
    }
    static List<Token> definition(String text, int line) {
        text += "\n";
        int[] positions = new int[text.length()];
        Arrays.fill(positions, line);
        List<Token> tokens = new ArrayList<>();
        for (LogicalLine logical : scan(text, positions, line))
            tokens.addAll(logical.tokens());
        return tokens;
    }
    static String render(List<Token> tokens) {
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < tokens.size(); i++) {
            Token token = tokens.get(i);
            if (i > 0 && token.space())
                result.append(' ');
            result.append(token.spelling());
        }
        return result.toString();
    }
    static String singleToken(String text) {
        if (text.isEmpty() || text.startsWith("//") || text.startsWith("/*"))
            return null;
        Read read = readToken(text, 0, false);
        return read.end() == text.length() ? read.kind() : null;
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class Main {
    static final Set<String> CONDITIONALS =
        Set.of("if", "ifdef", "ifndef", "elif", "elifdef", "elifndef", "else", "endif");
    static final class DirectiveError extends RuntimeException {
        DirectiveError(String message) { super(message); }
    }
    static final class Block {
        String kind;
        Definitions.Position position;
        boolean parent, chosen, active, elseSeen;
        Integer skipStart;
        Block(String kind, Definitions.Position position, boolean parent) {
            this.kind = kind;
            this.position = position;
            this.parent = parent;
        }
    }
    static final class Inclusion {
        IncludeManager.SourceFile source;
        int depth, offset;
        String displayFile;
        List<Block> stack = new ArrayList<>();
        List<Lexer.Token> segment = new ArrayList<>();
        Inclusion(IncludeManager.SourceFile source, int depth) {
            this.source = source;
            this.depth = depth;
            displayFile = source.path;
        }
        Definitions.Position position(int physical) {
            return new Definitions.Position(displayFile, physical + offset);
        }
        boolean skipping() { return !stack.isEmpty() && !stack.getLast().active; }
    }
    record Header(String rendering, String name, boolean quoted) {}
    record HeaderRead(Header header, int consumed) {}
    record Test(Long value, List<Lexer.Token> expanded) {}
    static boolean separatorNeeded(String left, String right) {
        return left.equals("/") && "/*".indexOf(right.charAt(0)) >= 0 ||
            Lexer.readToken(left + right, 0, false).end() != left.length();
    }
    static String outputRender(List<Lexer.Token> tokens) {
        StringBuilder result = new StringBuilder();
        String previous = null;
        for (Lexer.Token token : tokens) {
            if (previous != null && (token.space() || separatorNeeded(previous, token.spelling())))
                result.append(' ');
            result.append(token.spelling());
            previous = token.spelling();
        }
        return result.toString();
    }
    static String following(String heading, Collection<String> items) {
        return heading + (items.isEmpty() ? "" : " " + String.join(" ", items));
    }
    static HeaderRead headerSpecification(List<Lexer.Token> tokens, int position) {
        if (position >= tokens.size())
            return new HeaderRead(null, position);
        Lexer.Token token = tokens.get(position);
        if (token.kind().equals("string") || token.kind().equals("header")) {
            String text = token.spelling();
            return new HeaderRead(
                new Header(text, text.substring(1, text.length() - 1), text.startsWith("\"")),
                position + 1);
        }
        if (token.spelling().equals("<")) {
            int closing = position + 1;
            while (closing < tokens.size() && !tokens.get(closing).spelling().equals(">"))
                closing++;
            if (closing == tokens.size())
                throw new DirectiveError("missing terminating > character");
            String text = "<" + Lexer.render(tokens.subList(position + 1, closing)) + ">";
            return new HeaderRead(new Header(text, text.substring(1, text.length() - 1), false),
                                  closing + 1);
        }
        return new HeaderRead(null, position);
    }
    static boolean decimalToken(Lexer.Token token) {
        return token.kind().equals("number") && token.spelling().matches("[0-9]+");
    }
    static final class Preprocessor {
        Map<String, Definitions.Macro> macros = new TreeMap<>();
        Set<String> everDefined = new TreeSet<>(), poisoned = new HashSet<>();
        Map<String, List<Definitions.Macro>> saved = new HashMap<>();
        IncludeManager manager = new IncludeManager();
        Expander expander = new Expander(macros, this::diagnostic);
        List<String> output = new ArrayList<>(), history = new ArrayList<>(),
                     diagnostics = new ArrayList<>(), tree = new ArrayList<>(List.of("main.c")),
                     conditionalRecords = new ArrayList<>(), regions = new ArrayList<>();
        Map<String, Integer> diagnosticCounts = new HashMap<>(), conditionCounts = new HashMap<>();
        Definitions.Position previous;
        void diagnostic(Definitions.Position position, String kind, String message) {
            diagnostics.add(position + ": " + kind + ": " + message);
            diagnosticCounts.merge(kind, 1, Integer::sum);
        }
        void event(Definitions.Position position, String content) {
            history.add(position + ": " + content);
        }
        void poisonCheck(Inclusion context, List<Lexer.Token> tokens) {
            for (Lexer.Token token : tokens)
                if (token.kind().equals("identifier") && poisoned.contains(token.spelling()))
                    diagnostic(context.position(token.line()), "error",
                               "attempt to use poisoned \"" + token.spelling() + "\"");
        }
        void unusedCheck(Definitions.Macro macro) {
            if (macro.mainFile && macro.expanded == 0 && macro.tested == 0)
                diagnostic(macro.position, "warning", "macro \"" + macro.name + "\" is not used");
        }
        void define(List<Lexer.Token> tokens, Definitions.Position position, boolean mainFile) {
            Definitions.Macro macro;
            try {
                macro = Definitions.parse(tokens, position, mainFile);
            } catch (Definitions.DefinitionError error) {
                diagnostic(position, "error", error.getMessage());
                return;
            }
            Definitions.Macro previous = macros.get(macro.name);
            String operation;
            if (previous == null) {
                macros.put(macro.name, macro);
                everDefined.add(macro.name);
                operation = "define";
            } else if (previous.identical(macro))
                operation = "identical";
            else {
                unusedCheck(previous);
                diagnostic(position, "warning",
                           "\"" + macro.name + "\" redefined (previous definition at " +
                               previous.position + ")");
                macros.put(macro.name, macro);
                everDefined.add(macro.name);
                operation = "redefine";
            }
            event(position, operation + " " + macro.signature());
        }
        void undefine(List<Lexer.Token> tokens, Definitions.Position position) {
            String error = Definitions.checkName(tokens, "undef");
            if (error != null) {
                diagnostic(position, "error", error);
                return;
            }
            if (tokens.size() >= 2)
                diagnostic(position, "warning", "extra tokens at end of #undef directive");
            String name = tokens.getFirst().spelling();
            Definitions.Macro macro = macros.get(name);
            if (macro == null)
                event(position, "undef " + name + " (not defined)");
            else {
                unusedCheck(macro);
                macros.remove(name);
                event(position, "undef " + name);
            }
        }
        void processDefines() throws Exception {
            List<String> lines =
                Files.readAllLines(Path.of("input", "defines.txt"), StandardCharsets.US_ASCII);
            for (int i = 0; i < lines.size(); i++) {
                String line = lines.get(i);
                if (line.isEmpty())
                    continue;
                int equals = line.indexOf('=');
                String text = equals < 0
                                  ? line + " 1"
                                  : line.substring(0, equals) + " " + line.substring(equals + 1);
                define(Lexer.definition(text, i + 1),
                       new Definitions.Position("defines.txt", i + 1), false);
            }
        }
        void marker(String file, int line, Integer flag) {
            output.add("# " + line + " \"" + file + "\"" + (flag == null ? "" : " " + flag));
            previous = new Definitions.Position(file, line - 1);
        }
        void outputLine(Inclusion context, int physical, String text) {
            Definitions.Position position = context.position(physical);
            if (position.file().equals(previous.file()) && previous.line() < position.line() &&
                (long)position.line() <= (long)previous.line() + 8)
                for (int i = previous.line() + 1; i < position.line(); i++)
                    output.add("");
            else
                marker(position.file(), position.line(), null);
            output.add(text);
            previous = position;
            context.source.outputLines++;
        }
        void flush(Inclusion context) {
            List<Lexer.Token> segment = context.segment;
            context.segment = new ArrayList<>();
            if (segment.isEmpty())
                return;
            poisonCheck(context, segment);
            List<Lexer.Token> expanded = expander.expand(segment, context);
            int start = 0;
            while (start < expanded.size()) {
                int physical = expanded.get(start).line(), end = start + 1;
                while (end < expanded.size() && expanded.get(end).line() == physical)
                    end++;
                outputLine(context, physical, outputRender(expanded.subList(start, end)));
                start = end;
            }
        }
        boolean macroDefined(String name) {
            Definitions.Macro macro = macros.get(name);
            if (macro != null) {
                macro.tested++;
                return true;
            }
            return Definitions.BUILTINS.contains(name) || name.equals("__has_include");
        }
        List<Lexer.Token> replaceOperators(Inclusion context, List<Lexer.Token> operands) {
            List<Lexer.Token> replaced = new ArrayList<>();
            int position = 0;
            while (position < operands.size()) {
                Lexer.Token token = operands.get(position);
                int index;
                boolean value;
                if (token.kind().equals("identifier") && token.spelling().equals("defined")) {
                    index = position + 1;
                    boolean parenthesized =
                        index < operands.size() && operands.get(index).spelling().equals("(");
                    if (parenthesized)
                        index++;
                    if (index == operands.size() ||
                        !operands.get(index).kind().equals("identifier"))
                        throw new DirectiveError("operator \"defined\" requires an identifier");
                    String name = operands.get(index++).spelling();
                    if (parenthesized) {
                        if (index == operands.size() || !operands.get(index).spelling().equals(")"))
                            throw new DirectiveError("missing ')' after \"defined\"");
                        index++;
                    }
                    value = macroDefined(name);
                } else if (token.kind().equals("identifier") &&
                           token.spelling().equals("__has_include")) {
                    index = position + 1;
                    if (index == operands.size() || !operands.get(index).spelling().equals("("))
                        throw new DirectiveError("missing '(' after \"__has_include\"");
                    HeaderRead read = headerSpecification(operands, index + 1);
                    Header header = read.header();
                    index = read.consumed();
                    if (header == null || header.name().isEmpty())
                        throw new DirectiveError(
                            "operator \"__has_include\" requires a header-name");
                    if (index == operands.size() || !operands.get(index).spelling().equals(")"))
                        throw new DirectiveError("missing ')' after \"__has_include\" operand");
                    index++;
                    value = manager.search(header.name(), header.quoted()) != null;
                } else {
                    replaced.add(token);
                    position++;
                    continue;
                }
                replaced.add(
                    new Lexer.Token("number", value ? "1" : "0", token.line(), token.space()));
                position = index;
            }
            return replaced;
        }
        Test test(Inclusion context, Lexer.LogicalLine logical, String name,
                  List<Lexer.Token> operands) {
            Definitions.Position position = context.position(logical.tokens().getFirst().line());
            poisonCheck(context, operands);
            if (!name.equals("if") && !name.equals("elif")) {
                if (operands.isEmpty()) {
                    diagnostic(position, "error", "no macro name given in #" + name + " directive");
                    return new Test(null, null);
                }
                if (!operands.getFirst().kind().equals("identifier")) {
                    diagnostic(position, "error", "macro names must be identifiers");
                    return new Test(null, null);
                }
                if (operands.size() >= 2)
                    diagnostic(position, "warning",
                               "extra tokens at end of #" + name + " directive");
                boolean defined = macroDefined(operands.getFirst().spelling()),
                        value =
                            name.equals("ifndef") || name.equals("elifndef") ? !defined : defined;
                return new Test(value ? 1L : 0L, null);
            }
            List<Lexer.Token> replaced;
            try {
                replaced = replaceOperators(context, operands);
            } catch (DirectiveError error) {
                diagnostic(position, "error", error.getMessage());
                return new Test(null, null);
            }
            List<Lexer.Token> expanded = expander.expand(replaced, context);
            try {
                Expression.Node expression = Expression.parse(expanded, name);
                long value = Expression.evaluate(
                    expression, message -> diagnostic(position, "warning", message));
                return new Test(value, expanded);
            } catch (Expression.ExpressionError error) {
                diagnostic(position, "error", error.getMessage());
                return new Test(null, expanded);
            }
        }
        String testDescription(String name, Test test) {
            String description;
            if (test.value() == null)
                description = "not taken (error)";
            else {
                description = test.value() != 0 ? "taken" : "not taken";
                if (name.equals("if") || name.equals("elif"))
                    description += " (value " + test.value() + ")";
            }
            if (test.expanded() != null)
                description += " [" + outputRender(test.expanded()) + "]";
            return description;
        }
        void closeRegion(Inclusion context, Block block, int end) {
            Integer start = block.skipStart;
            if (start != null && end >= start) {
                Definitions.Position first = context.position(start), last = context.position(end);
                regions.add(first + "-" + last.line() + " lines=" + (end - start + 1));
                context.source.skippedLines += end - start + 1;
            }
            block.skipStart = null;
        }
        void conditionalRecord(Definitions.Position position, int depth, String name,
                               List<Lexer.Token> operands, String description) {
            String directive =
                "#" + name + (operands.isEmpty() ? "" : " " + Lexer.render(operands));
            conditionalRecords.add(position + ": "
                                   + "  ".repeat(depth) + directive + " => " + description);
            String[][] categories = {{"taken", "taken"},
                                     {"not taken", "not_taken"},
                                     {"skipped", "skipped"},
                                     {"not evaluated", "not_evaluated"},
                                     {"closes", "endif"}};
            for (String[] category : categories)
                if (description.startsWith(category[0])) {
                    conditionCounts.merge(category[1], 1, Integer::sum);
                    break;
                }
        }
        void conditional(Inclusion context, Lexer.LogicalLine logical, String name,
                         List<Lexer.Token> operands) {
            Definitions.Position position = context.position(logical.tokens().getFirst().line());
            if (IncludeManager.STARTS.contains(name)) {
                boolean parent = context.stack.isEmpty() || context.stack.getLast().active;
                Block block = new Block(name, position, parent);
                String description;
                if (parent) {
                    Test test = test(context, logical, name, operands);
                    if (test.value() != null && test.value() != 0)
                        block.chosen = block.active = true;
                    else
                        block.skipStart = logical.end() + 1;
                    description = testDescription(name, test);
                } else
                    description = "skipped";
                conditionalRecord(position, context.stack.size(), name, operands, description);
                context.stack.add(block);
                return;
            }
            if (context.stack.isEmpty()) {
                diagnostic(position, "error", "#" + name + " without #if");
                return;
            }
            Block block = context.stack.getLast();
            int depth = context.stack.size() - 1;
            closeRegion(context, block, logical.start() - 1);
            String description;
            if (name.equals("endif")) {
                context.stack.removeLast();
                if (block.parent && !operands.isEmpty())
                    diagnostic(position, "warning", "extra tokens at end of #endif directive");
                description = "closes #" + block.kind + " at line " + block.position.line();
            } else {
                if (block.elseSeen)
                    diagnostic(position, "error", "#" + name + " after #else");
                if (name.equals("else")) {
                    if (block.parent && !operands.isEmpty())
                        diagnostic(position, "warning", "extra tokens at end of #else directive");
                    block.elseSeen = true;
                    if (block.parent) {
                        block.active = !block.chosen;
                        block.chosen = true;
                        description = block.active ? "taken" : "not taken";
                    } else {
                        block.active = false;
                        description = "skipped";
                    }
                } else if (!block.parent) {
                    block.active = false;
                    description = "skipped";
                } else if (block.chosen) {
                    block.active = false;
                    description = "not evaluated";
                } else {
                    Test test = test(context, logical, name, operands);
                    block.active = test.value() != null && test.value() != 0;
                    if (block.active)
                        block.chosen = true;
                    description = testDescription(name, test);
                }
                if (block.parent && !block.active)
                    block.skipStart = logical.end() + 1;
            }
            conditionalRecord(position, depth, name, operands, description);
        }
        void include(Inclusion context, Lexer.LogicalLine logical, List<Lexer.Token> operands)
            throws Exception {
            Definitions.Position position = context.position(logical.tokens().getFirst().line());
            Header header;
            try {
                List<Lexer.Token> sequence = operands;
                HeaderRead read = headerSpecification(sequence, 0);
                if (read.header() == null && !sequence.isEmpty()) {
                    sequence = expander.expand(sequence, context);
                    read = headerSpecification(sequence, 0);
                }
                header = read.header();
                if (header == null)
                    throw new DirectiveError("#include expects \"FILENAME\" or <FILENAME>");
                if (read.consumed() < sequence.size())
                    diagnostic(position, "warning", "extra tokens at end of #include directive");
                if (header.name().isEmpty())
                    throw new DirectiveError("empty filename in #include");
            } catch (DirectiveError error) {
                diagnostic(position, "error", error.getMessage());
                return;
            }
            String prefix =
                       "  ".repeat(context.depth + 1) + logical.tokens().getFirst().line() + ": ",
                   path = manager.search(header.name(), header.quoted());
            if (path == null) {
                tree.add(prefix + header.rendering() + " [not found]");
                diagnostic(position, "error", "cannot find include file " + header.rendering());
                return;
            }
            IncludeManager.SourceFile previous = manager.files.get(path);
            if (previous != null && previous.once) {
                tree.add(prefix + path + " [skipped: pragma once]");
                previous.skipped++;
                return;
            }
            if (previous != null && previous.guard != null && macros.containsKey(previous.guard)) {
                tree.add(prefix + path + " [skipped: guard " + previous.guard + "]");
                previous.skipped++;
                return;
            }
            if (context.depth + 1 > 8) {
                tree.add(prefix + path + " [too deep]");
                diagnostic(position, "error", "#include nested too deeply");
                return;
            }
            tree.add(prefix + path);
            marker(path, 1, 1);
            processFile(path, context.depth + 1);
            Definitions.Position resumed = context.position(logical.end() + 1);
            marker(resumed.file(), resumed.line(), 2);
        }
        void lineDirective(Inclusion context, Lexer.LogicalLine logical,
                           List<Lexer.Token> operands) {
            Definitions.Position position = context.position(logical.tokens().getFirst().line());
            if (operands.isEmpty() || !decimalToken(operands.getFirst()))
                operands = expander.expand(operands, context);
            if ((operands.size() != 1 && operands.size() != 2) ||
                !decimalToken(operands.getFirst()) ||
                operands.size() == 2 && !operands.get(1).kind().equals("string")) {
                diagnostic(position, "error", "invalid #line directive");
                return;
            }
            long line = Long.parseLong(operands.getFirst().spelling());
            if (line < 1 || line > Integer.MAX_VALUE) {
                diagnostic(position, "error", "line number out of range");
                return;
            }
            context.offset = (int)line - (logical.end() + 1);
            if (operands.size() == 2) {
                String spelling = operands.get(1).spelling();
                context.displayFile = spelling.substring(1, spelling.length() - 1);
            }
        }
        void macroPragma(Definitions.Position position, List<Lexer.Token> operands,
                         String operation) {
            if (operands.size() != 4 || !operands.get(1).spelling().equals("(") ||
                !operands.get(2).kind().equals("string") ||
                !operands.get(3).spelling().equals(")")) {
                diagnostic(position, "error", "invalid #pragma " + operation + " directive");
                return;
            }
            String spelling = operands.get(2).spelling(),
                   name = spelling.substring(1, spelling.length() - 1);
            List<Definitions.Macro> stack =
                saved.computeIfAbsent(name, ignored -> new ArrayList<>());
            if (operation.equals("push_macro")) {
                stack.add(macros.get(name));
                event(position, "push " + name);
            } else if (stack.isEmpty())
                diagnostic(position, "warning", "no matching push_macro for \"" + name + "\"");
            else {
                Definitions.Macro macro = stack.removeLast();
                if (macro == null) {
                    macros.remove(name);
                    event(position, "pop " + name + " (undefined)");
                } else {
                    macros.put(name, macro);
                    event(position, "pop " + name);
                }
            }
        }
        void pragma(Inclusion context, Lexer.LogicalLine logical, List<Lexer.Token> operands) {
            Definitions.Position position = context.position(logical.tokens().getFirst().line());
            String name = !operands.isEmpty() && operands.getFirst().kind().equals("identifier")
                              ? operands.getFirst().spelling()
                              : null;
            if ("once".equals(name)) {
                if (operands.size() >= 2)
                    diagnostic(position, "warning",
                               "extra tokens at end of #pragma once directive");
                if (context.depth == 0)
                    diagnostic(position, "warning", "#pragma once in main file");
                context.source.once = true;
            } else if (operands.size() >= 2 && operands.get(0).spelling().equals("GCC") &&
                       operands.get(1).spelling().equals("poison")) {
                for (Lexer.Token token : operands.subList(2, operands.size()))
                    if (!token.kind().equals("identifier")) {
                        diagnostic(position, "error", "invalid #pragma GCC poison directive");
                        return;
                    }
                for (Lexer.Token token : operands.subList(2, operands.size())) {
                    if (macros.containsKey(token.spelling()))
                        diagnostic(position, "warning",
                                   "poisoning existing macro \"" + token.spelling() + "\"");
                    poisoned.add(token.spelling());
                }
            } else if ("push_macro".equals(name) || "pop_macro".equals(name))
                macroPragma(position, operands, name);
            else
                outputLine(context, logical.tokens().getFirst().line(),
                           "#pragma" + (operands.isEmpty() ? "" : " " + Lexer.render(operands)));
        }
        void directive(Inclusion context, Lexer.LogicalLine logical, String name,
                       List<Lexer.Token> operands) throws Exception {
            if (logical.tokens().size() == 1)
                return;
            boolean poisoning = "pragma".equals(name) && operands.size() >= 2 &&
                                operands.get(0).spelling().equals("GCC") &&
                                operands.get(1).spelling().equals("poison");
            if (!poisoning)
                poisonCheck(context, operands);
            Definitions.Position position = context.position(logical.tokens().getFirst().line());
            if ("define".equals(name))
                define(operands, position, context.depth == 0);
            else if ("undef".equals(name))
                undefine(operands, position);
            else if ("include".equals(name))
                include(context, logical, operands);
            else if ("line".equals(name))
                lineDirective(context, logical, operands);
            else if ("error".equals(name) || "warning".equals(name))
                diagnostic(position, name,
                           "#" + name + (operands.isEmpty() ? "" : " " + Lexer.render(operands)));
            else if ("pragma".equals(name))
                pragma(context, logical, operands);
            else
                diagnostic(position, "error",
                           "invalid preprocessing directive #" +
                               logical.tokens().get(1).spelling());
        }
        void processFile(String path, int depth) throws Exception {
            IncludeManager.SourceFile source = manager.load(path);
            source.entered++;
            Inclusion context = new Inclusion(source, depth);
            for (Lexer.LogicalLine logical : source.lines) {
                List<Lexer.Token> tokens = logical.tokens();
                boolean directive = !tokens.isEmpty() && tokens.getFirst().spelling().equals("#");
                String name = IncludeManager.directiveName(tokens);
                List<Lexer.Token> operands =
                    tokens.subList(Math.min(2, tokens.size()), tokens.size());
                if (directive && name != null && CONDITIONALS.contains(name)) {
                    flush(context);
                    conditional(context, logical, name, operands);
                } else if (context.skipping())
                    continue;
                else if (directive) {
                    flush(context);
                    directive(context, logical, name, operands);
                } else
                    context.segment.addAll(tokens);
            }
            flush(context);
            for (Block block : context.stack)
                closeRegion(context, block, source.physicalLines);
            for (Block block : context.stack)
                diagnostic(block.position, "error", "unterminated #" + block.kind);
        }
        List<String> includeReport() {
            List<String> lines = new ArrayList<>(tree);
            lines.add("");
            lines.add("== files ==");
            for (String path : new TreeSet<>(manager.files.keySet())) {
                IncludeManager.SourceFile source = manager.files.get(path);
                lines.add(path + " entered=" + source.entered + " skipped=" + source.skipped +
                          " lines=" + source.physicalLines + " output_lines=" + source.outputLines +
                          " skipped_lines=" + source.skippedLines +
                          " guard=" + (source.guard == null ? "-" : source.guard) +
                          " once=" + (source.once ? "yes" : "no"));
            }
            lines.add("");
            String current = "main.o:";
            boolean hasPath = false;
            for (String path : manager.files.keySet()) {
                if (current.length() + 1 + path.length() > 76 && hasPath) {
                    lines.add(current + " \\");
                    current = " ";
                    hasPath = false;
                }
                current += " " + path;
                hasPath = true;
            }
            lines.add(current);
            return lines;
        }
        Map<String, List<String>> references() {
            Map<String, List<String>> references = new TreeMap<>();
            for (var entry : macros.entrySet()) {
                Definitions.Macro macro = entry.getValue();
                Set<String> names = new TreeSet<>();
                for (Lexer.Token token : macro.replacement)
                    if (token.kind().equals("identifier") && macros.containsKey(token.spelling()) &&
                        (macro.parameters == null || !macro.parameters.contains(token.spelling())))
                        names.add(token.spelling());
                references.put(entry.getKey(), List.copyOf(names));
            }
            return references;
        }
        boolean recursive(String name, Map<String, List<String>> references) {
            Deque<String> pending = new ArrayDeque<>(references.get(name));
            Set<String> seen = new HashSet<>();
            while (!pending.isEmpty()) {
                String current = pending.pop();
                if (current.equals(name))
                    return true;
                if (seen.add(current))
                    pending.addAll(references.get(current));
            }
            return false;
        }
        List<String> macroReport() {
            List<String> lines = new ArrayList<>();
            lines.add("== history ==");
            lines.addAll(history);
            lines.add("");
            lines.add("== table ==");
            Map<String, List<String>> references = references();
            int objectLike = 0;
            for (var entry : macros.entrySet()) {
                Definitions.Macro macro = entry.getValue();
                if (macro.parameters == null)
                    objectLike++;
                lines.add(
                    "#define " + macro.signature() +
                    (macro.replacement.isEmpty() ? "" : " " + Lexer.render(macro.replacement)));
                lines.add("  at " + macro.position + " expanded=" + macro.expanded +
                          " tested=" + macro.tested +
                          " recursive=" + (recursive(macro.name, references) ? "yes" : "no"));
                lines.add(following("  refs:", references.get(macro.name)));
            }
            lines.add("");
            lines.add("macros=" + macros.size() + " object_like=" + objectLike +
                      " function_like=" + (macros.size() - objectLike));
            Set<String> undefined = new TreeSet<>(everDefined);
            undefined.removeAll(macros.keySet());
            lines.add(following("undefined:", undefined));
            lines.add(
                "builtins: __COUNTER__=" + expander.builtinCounts.getOrDefault("__COUNTER__", 0) +
                " __FILE__=" + expander.builtinCounts.getOrDefault("__FILE__", 0) +
                " __LINE__=" + expander.builtinCounts.getOrDefault("__LINE__", 0));
            return lines;
        }
        List<String> conditionalReport() {
            List<String> lines = new ArrayList<>(conditionalRecords);
            lines.add("");
            lines.add("== skipped regions ==");
            lines.addAll(regions);
            lines.add("");
            lines.add("directives=" + conditionalRecords.size() +
                      " taken=" + conditionCounts.getOrDefault("taken", 0) +
                      " not_taken=" + conditionCounts.getOrDefault("not_taken", 0) +
                      " skipped=" + conditionCounts.getOrDefault("skipped", 0) +
                      " not_evaluated=" + conditionCounts.getOrDefault("not_evaluated", 0) +
                      " endif=" + conditionCounts.getOrDefault("endif", 0) +
                      " regions=" + regions.size());
            return lines;
        }
        void writeReports() throws Exception {
            Files.createDirectories(Path.of("output"));
            List<String> diagnosticLines = new ArrayList<>(diagnostics);
            diagnosticLines.add("errors=" + diagnosticCounts.getOrDefault("error", 0) +
                                " warnings=" + diagnosticCounts.getOrDefault("warning", 0));
            write("preprocessed.txt", output);
            write("includes.txt", includeReport());
            write("macros.txt", macroReport());
            write("conditionals.txt", conditionalReport());
            write("diagnostics.txt", diagnosticLines);
        }
        void run() throws Exception {
            processDefines();
            marker("main.c", 1, null);
            processFile("main.c", 0);
            for (Definitions.Macro macro : macros.values())
                unusedCheck(macro);
            writeReports();
        }
    }
    static void write(String name, List<String> lines) throws Exception {
        StringBuilder text = new StringBuilder();
        for (String line : lines) {
            int end = line.length();
            while (end > 0 && line.charAt(end - 1) == ' ')
                end--;
            text.append(line, 0, end).append('\n');
        }
        Files.writeString(Path.of("output", name), text, StandardCharsets.US_ASCII);
    }
    public static void main(String[] args) throws Exception { new Preprocessor().run(); }
